/**
 * The types `save/milestones/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    MilestoneTierClaimsSaveRow, MilestonesSaveExtract
 * depends    —
 * used by    src/save/milestones/index, src/save/milestones/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

/** One tier's milestone track as the save records it. */
export interface MilestoneTierClaimsSaveRow {
  tier: number
  /** Reward slots claimed on the free track, by the slot index the game uses within the tier. */
  claimedSlots: number[]
  /** Reward slots claimed on the premium track. */
  premiumClaimedSlots: number[]
  /** Whether the premium pass covering this tier is owned. */
  premiumUnlocked: boolean
}

export interface MilestonesSaveExtract {
  /** Reward slots per tier, as the save lays the claim lists out. */
  slotsPerTier: number
  /** Tiers with at least one claim or an owned premium pass, lowest first. */
  tiers: MilestoneTierClaimsSaveRow[]
  warnings: string[]
}
